INSERT INTO `stories` (`id`, `user_id`, `title`, `synopsis`, `language`, `genres`, `tags`, `warnings`, `is_fanfiction`, `format`, `cover_image`, `is_premium`, `price`, `story_progress`, `views`, `likes`, `earnings`, `content`, `created_at`, `updated_at`, `rating`, `ratings_count`, `story_approval_status`, `story_status`, `is_hidden`) VALUES
(1, 1, 'The Last Lantern on Ashmoor', 'A windswept coastal road at dusk. In the foreground, a young lantern keeper stands in a hooded cloak holding a glowing brass lantern. The lantern light reveals fog curling around toppled stone markers. Behind them, a cliffside village of black slate roofs sits half-hidden in mist. Farther back, an ancient ruin rises like a broken crown, and faint blue runes flicker in its arches. The palette is midnight blue, sea-foam green, and warm amber lantern glow. Cinematic, high detail, slightly painterly style.', 'English', '[\"Adventure\", \"Fantasy\"]', '[\"Magic\"]', NULL, 0, 'serialized', 'covers/ZdGMKQdUeVB5CuXxI0cXJigihslcQNoBIIgRvD4F.jpg', 0, NULL, 'published', 31, 0, 0, NULL, '2026-05-09 12:20:16', '2026-06-21 13:48:46', 4.50, 2, 'approved', 'ongoing', 0),
(2, 1, 'សំបុត្រដែលមកយឺត', 'សៅ មើលឃើញសំបុត្រចាស់មួយដាក់នៅមុខទ្វារផ្ទះរបស់គាត់ ទាំងដែលគាត់មិនដឹងថា អ្នកណាជាអ្នកផ្ញើ។ នៅលើសំបុត្រសរសេរថា “បើអ្នកអានវា អ្នកនឹងអាចជួសជុលអ្វីមួយដែលខកខានកន្លងមក”។ ពេលសៅអានមើល ស្រាប់តែពេលវេលាចាប់ផ្តើមផ្លាស់ប្តូរ ហើយគាត់ត្រូវជ្រើសរើសថា តើគាត់នឹងកែប្រែអ្វីដែលធ្លាប់ខកខាន ឬទុកឲ្យអតីតកាលនៅដូចមុន។', 'Khmer', '[\"Comedy\", \"Short Story\"]', '[]', NULL, 0, 'serialized', 'covers/ocsUzrwPWXYxpdR7Nhlk88Oz9sgIsuiqogMClwHX.jpg', 0, NULL, 'published', 13, 0, 0, NULL, '2026-05-09 12:23:45', '2026-06-21 13:49:35', 0.00, 0, 'approved', 'ongoing', 0),
(3, 1, 'ស្នាមញញឹមនៅចុងផ្លូវ', 'នៅពេលនាង “សុវណ្ណរ័ត្ន” រស់នៅក្នុងទីក្រុងដែលពោរពេញដោយអាថ៌កំបាំង នាងបានជួបនឹងស្នាមញញឹមចម្លែកមួយលើក្រដាសចាស់ ដែលនាំឲ្យនាងត្រូវតាមស្រាវជ្រាវអតីតកាលរបស់មនុស្សម្នាក់។ រឿងនេះនឹងបង្ហាញថា ស្នេហាមិនត្រឹមតែជាក្តីស្រឡាញ់ទេ ប៉ុន្តែជាការអភ័យទោស ការជឿជាក់ និងការហ៊ានចាប់ផ្តើមថ្មី—ទោះបីអតីតកាលនៅតាមដានយ៉ាងណាក៏ដោយ។', 'Khmer', '[\"Mystery\", \"Romance\"]', '[\"Romance Subplot\"]', NULL, 0, 'serialized', 'covers/TkZYFsRRAWip72TZfb7MGApfC6NaN0GmzZeNeOeN.webp', 0, 0, 'published', 13, 0, 0, NULL, '2026-05-10 01:33:06', '2026-06-21 13:49:37', 0.00, 0, 'approved', 'ongoing', 0),
(5, 1, 'Hidden Love', 'Sang Zhi first meets Duan Jiaxu when she is still in middle school. He is her older brother’s best friend, warm and caring, and he unintentionally becomes her first crush. As Sang Zhi grows older, her feelings deepen quietly, but because of the age difference and life circumstances, they drift apart.\r\n\r\nYears later, Sang Zhi enters university in the same city where Duan Jiaxu lives. Meeting again as adults, their relationship slowly changes from a secret one-sided crush into genuine love as they help each other heal from emotional wounds and grow together.', 'English', '[\"Comedy\", \"Drama\", \"Romance\"]', '[\"Female Lead\", \"Male Lead\", \"School Life\"]', NULL, 0, 'serialized', 'covers/KxlClJHHWqmQG6SeuqjVpNsFXBDaLFGo4wCBvgkJ.jpg', 0, NULL, 'published', 23, 0, 0, NULL, '2026-05-10 02:54:45', '2026-06-13 08:04:27', 4.00, 1, 'approved', 'ongoing', 0),
(9, 1, 'The First Frost', 'After years apart, Wen Yifan reunites with her high school crush, Sang Yan, when fate unexpectedly makes them roommates. As old memories resurface, the two slowly heal from past wounds and rediscover a love that never truly disappeared.', 'English', '[\"Comedy\", \"Drama\", \"Romance\"]', '[\"Female Lead\", \"Male Lead\", \"Comedy\", \"Youth Love\", \"Friendship\"]', NULL, 0, 'serialized', NULL, 0, NULL, 'published', 1, 0, 0, NULL, '2026-05-12 20:03:15', '2026-06-01 11:36:16', 2.00, 1, 'approved', 'ongoing', 0),
(13, 1, 'hello', 'hi', 'English', '[\"Mystery\", \"Slice of Life\"]', '[\"Childhood Friends\", \"Family Saga\"]', NULL, 0, 'serialized', NULL, 0, NULL, 'published', 3, 0, 0, NULL, '2026-05-24 14:24:02', '2026-06-01 11:26:34', 0.00, 0, 'approved', 'ongoing', 0),
(14, 1, 'welcome to the world', 'There are 21 people in the NCT', 'English', '[\"Drama\", \"Satire\"]', '[\"Futuristic\", \"War Strategy\"]', NULL, 0, 'serialized', NULL, 0, NULL, 'published', 2, 0, 0, NULL, '2026-05-26 10:32:41', '2026-06-01 12:48:53', 0.00, 0, 'approved', 'ongoing', 0),
(15, 1, 'We are one', 'There are 12 men who would to complete their dream as the KPOP Group, and they made their debut on 8 April 2012 under SM which the group name EXO.', 'English', '[\"Romance\", \"Short Story\"]', '[\"Reverse Harem\", \"Game System\", \"Historical\"]', NULL, 0, 'serialized', NULL, 0, NULL, 'published', 1, 0, 0, NULL, '2026-05-26 10:36:24', '2026-06-21 13:49:24', 0.00, 0, 'approved', 'ongoing', 0),
(16, 1, 'The Map That Only Appears at Night', 'Mira discovers an old compass in her late grandmother’s house—except it doesn’t point north. When she follows the compass during a midnight walk, glowing lines appear in the air like ink made of moonlight. They form a map… but the map only exists between 12:00 and 12:17 a.m., and every time Mira tries to save it, it disappears.\r\n\r\nAs Mira uncovers what the compass wants, she learns the map is tied to a long-forgotten promise: a missing person, a hidden staircase beneath the town library, and a secret that has been protected for decades. But the closer Mira gets to the truth, the more someone else seems to know where she’s heading—leaving her with a frightening question:\r\n\r\nIs the map guiding her… or leading her into a trap?', 'English', '[\"Fantasy\", \"Mystery\", \"Thriller\"]', '[\"Slow Burn\", \"Cultivation\", \"Mystery\", \"Thriller\"]', NULL, 0, 'serialized', NULL, 0, NULL, 'published', 18, 0, 0, NULL, '2026-05-26 10:51:14', '2026-06-21 13:48:42', 4.00, 1, 'approved', 'complete', 0),
(17, 1, 'momo', 'momo love momo', 'English', '[\"Drama\", \"Dark Fantasy\"]', '[\"Virtual Reality\", \"Time Loop\"]', NULL, 0, 'serialized', NULL, 0, 0, 'published', 10, 0, 0, NULL, '2026-05-28 10:23:24', '2026-06-21 13:49:04', 0.00, 0, 'approved', 'ongoing', 0),
(21, 1, 'When I Fly Towards You', 'When I Fly Towards You is a heartwarming coming-of-age love story about a cheerful and optimistic girl, Su Zaizai, who falls for a quiet and gentle top student, Zhang Lurang.\r\n\r\nTheir story begins in high school, where Zaizai’s bright personality slowly melts Lurang’s cold exterior. Along with their close group of friends, they experience friendship, academic pressure, personal growth, and first love.\r\n\r\nThe story beautifully follows their journey from youthful crushes to deeper emotional connections, showing how love and friendship shape their lives over time.', 'English', '[\"Drama\", \"Romance\"]', '[\"Female Lead\", \"Male Lead\", \"School Life\", \"Friends to Lovers\", \"Youth Love\", \"Friendship\"]', '[\"AI-Assisted Content\", \"AI-Generated Content\"]', 1, 'serialized', 'covers/0CbWNHe4kjhXl0bpUEWQOTf3ASHBTwsyGubJc5Z9.webp', 0, NULL, 'published', 9, 0, 0, NULL, '2026-06-01 10:26:47', '2026-06-21 13:49:16', 0.00, 0, 'approved', 'ongoing', 0),
(23, 1, 'Confession', 'This is a modern romance web novel about love, growth, and emotional healing.\r\n\r\nThe story follows Xu Sui, a quiet and gentle girl who had a long-time crush on a popular and carefree boy, Zhou Jingze, since high school.\r\n\r\nYears later, they meet again in university.\r\nAt first, they seem like people from completely different worlds—\r\n\r\nHe is charming, rebellious, and surrounded by girls\r\nShe is calm, hardworking, and often overlooked\r\n\r\nOne night, during a gathering, Xu Sui gathers her courage and confesses her feelings… only to be rejected coldly.\r\n\r\nHowever, fate keeps bringing them together. As time passes:\r\n\r\nmisunderstandings happen\r\nemotions deepen\r\npast wounds resurface\r\n\r\nSlowly, Zhou Jingze begins to change, and their relationship evolves from one-sided love into something deeper—but also more complicated.', 'English', '[\"Drama\", \"Romance\"]', '[\"Female Lead\", \"Male Lead\", \"School Life\", \"Slow Burn\", \"Modern Day\", \"Youth Love\"]', '[\"AI-Generated Content\"]', 0, 'serialized', 'covers/NZnVmaAuZHuCT0WlYzagNVwdYhgNWgoJZuQ8uPeN.jpg', 0, NULL, 'published', 20, 0, 0, NULL, '2026-06-08 12:04:43', '2026-06-21 12:56:01', 0.00, 0, 'approved', 'ongoing', 0),
(24, 1, 'ពន្លឺក្រោមព្រះច័ន្ទ', 'រឿងស្នេហាដ៏ស្ងប់ស្ងាត់ ប៉ុន្តែជ្រាលជ្រៅ រវាងនិស្សិតស្រីម្នាក់ឈ្មោះស្រីនាង និងកំលោះម្នាក់ឈ្មោះដារា ដែលពោរពេញដោយអាថ៌កំបាំង។ ពួកគេចាប់ផ្តើមពីមិត្តភាពធម្មតា បន្តទៅជាស្នេហាដែលពោរពេញដោយភាពកក់ក្តៅ និងសុបិនរួមគ្នា។\r\n\r\nប៉ុន្តែស្នេហានោះត្រូវប្រឈមមុខនឹងការសាកល្បងដ៏ធំមួយ នៅពេលស្រីនាងរកឃើញថាដារាមានជំងឺធ្ងន់។ ទោះជាពេលវេលាមានកំណត់ ពួកគេនៅតែជ្រើសរើសរស់នៅក្នុងគ្រាដែលមានន័យ និងរក្សាស្នេហារបស់ពួកគេឲ្យភ្លឺដូចពន្លឺព្រះច័ន្ទ។\r\n\r\nរឿងនេះបង្ហាញពីសារៈសំខាន់នៃការស្រឡាញ់ ការបាត់បង់ និងការរស់បន្ត ទោះបីជាអ្នកដែលយើងស្រឡាញ់មិននៅជាមួយយើងទៀតក៏ដោយ។', 'Khmer', '[\"Romance\", \"Tragedy\", \"Slice of Life\"]', '[\"Slow Burn\", \"Slice of Life\", \"Tragedy\", \"Youth Love\"]', '[]', 0, 'serialized', 'covers/UQwRyd8KA11GW605bLI2J4SelP9Z8XVBtSXJFhXR.png', 0, NULL, 'published', 12, 0, 0, NULL, '2026-06-14 08:35:03', '2026-06-21 13:48:53', 0.00, 0, 'approved', 'ongoing', 0);

